"""Club-level currencies, inherited by tables; local flags and searchable countries.

Country/currency names and current region mappings: Unicode CLDR 48,
https://github.com/unicode-org/cldr-json, snapshot 2026-10-23.
Flag thumbnails derived from flag-icons 7.3.2 (MIT), https://github.com/lipis/flag-icons.
Full third-party copyright and permission notices are embedded below.
"""
from html import escape
import base64
import json
import secrets
import zlib

MAX_CURRENCY_LENGTH = 24


def normalize_currency(value, required=True):
    raw = str(value or '').strip()
    code = ' '.join(raw.split()).upper()
    if code and len(code) <= MAX_CURRENCY_LENGTH and all(ch.isprintable() for ch in raw) and '<' not in code and '>' not in code:
        return code
    if required:
        raise ValueError('Choose the club currency (up to 24 characters), for example USD or USDT.')
    return ''


CRYPTO = [('USDT','Tether','₮'),('USDC','USD Coin','◈'),('BTC','Bitcoin','₿'),('ETH','Ethereum','Ξ'),('TRX','TRON','◈'),('SOL','Solana','◎'),('TON','Toncoin','◈'),('BNB','BNB','◈'),('XRP','XRP','◈'),('ADA','Cardano','◈'),('DOGE','Dogecoin','Ð')]


def _flag_for(code):
    if code == 'EUR':
        return 'eu'
    # Shared currencies do not imply that a club is located in a particular country.
    if code in ('XAF','XOF','XCD','XCG','XPF'):
        return ''
    region = code[:2].lower()
    return region if any(row[0].lower()==region and row[2]==code for row in _DATA['rows']) else ''


def currency_badge(value):
    code = normalize_currency(value, required=False)
    if not code:
        return ''
    safe = escape(code, quote=True)
    flag = _flag_for(code)
    if flag and flag in _DATA['flags']:
        icon = '<img src="data:image/webp;base64,'+_DATA['flags'][flag]+'" width="20" height="15" alt="" style="display:block;border-radius:2px;object-fit:contain">'
    else:
        symbol = next((symbol for token,name,symbol in CRYPTO if token==code),'¤')
        icon = '<span aria-hidden="true" style="display:inline-flex;align-items:center;justify-content:center;width:20px;height:16px;border:1px solid #a8d8c455;border-radius:4px;color:#c7e8da;font-size:12px;line-height:1">'+symbol+'</span>'
    return '<span class="tr-currency" role="img" tabindex="0" aria-label="Game currency '+safe+'" title="'+safe+' · Club currency" style="display:block;width:max-content;max-width:100%;margin-top:4px;line-height:1">'+icon+'</span>'


def currency_input(value=''):
    code=normalize_currency(value,required=False)
    safe=escape(str(value or ''),quote=True)
    picker_id='currency-'+secrets.token_hex(6)
    rows=list(dict.fromkeys(tuple(row) for row in _DATA['rows']))
    rows += [('CR',name,token,name) for token,name,symbol in CRYPTO]
    if code and not any(row[2]==code for row in rows):
        rows.append(('CUSTOM','Custom currency / token',code,code))
    payload=json.dumps(dict(id=picker_id,rows=rows,flags=_DATA['flags']),ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    return f'''<span class="tr-currency-picker" style="display:block;position:relative;min-width:0"><input data-currency-search name="currency" type="text" required maxlength="80" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="{picker_id}" aria-label="Club currency: search country or currency" placeholder="Search USA, Great Britain, USD, USDT…" value="{safe}" autocomplete="off" spellcheck="false"><input data-currency-value name="currency" type="hidden" disabled value="{safe}"><span data-currency-options id="{picker_id}" class="tr-currency-options" role="listbox" aria-label="Countries and currencies" hidden></span><small data-currency-hint style="display:block;font-size:11px;color:#a5b4b6;margin-top:5px;line-height:1.4">Used automatically by every table in this club.</small><script type="application/json" data-currency-data>{payload}</script><style>.tr-currency-picker .tr-currency-options[hidden]{{display:none!important}}.tr-currency-picker .tr-currency-options{{position:absolute;left:0;right:0;top:54px;z-index:50;max-height:240px;overflow:auto;border:1px solid #7b9f99;border-radius:9px;background:#17272b;box-shadow:0 12px 28px #0007;padding:4px}}.tr-currency-picker .tr-currency-options button{{display:flex;align-items:center;gap:8px;width:100%;min-height:32px;text-align:left;border:0;border-radius:5px;background:transparent;color:#e1efea;padding:7px 8px;font-family:inherit;font-size:12px;line-height:1.4;cursor:pointer;white-space:normal;box-sizing:border-box}}.tr-currency-picker .tr-currency-options button:hover,.tr-currency-picker .tr-currency-options button[aria-selected="true"]{{background:#a8d8c425;color:#d3f3e4}}.tr-currency-picker img{{flex:none;border-radius:2px;object-fit:contain}}.tr-currency-token{{display:inline-flex;justify-content:center;width:20px;flex:none;color:#b5dfcd}}.tr-currency-empty{{display:block;padding:8px;font-size:12px;color:#a5b4b6}}</style><script>{_PICKER_JS}</script></span>'''


