_DATA=json.loads(zlib.decompress(base64.b64decode('')))
_PICKER_JS="(function(){\nconst root=document.currentScript.parentElement,field=root.querySelector('[data-currency-search]'),selected=root.querySelector('[data-currency-value]'),list=root.querySelector('[data-currency-options]'),hint=root.querySelector('[data-currency-hint]'),data=JSON.parse(root.querySelector('[data-currency-data]').textContent);\nfield.removeAttribute('name');selected.disabled=false;\nlet chosen=selected.value,index=-1;\nconst aliases={US:'usa america american dollar',GB:'uk great britain england sterling pound',SA:'saudi arabia riyal',AE:'uae emirates dirham',EU:'europe euro euros'};\nfunction close(){list.hidden=true;field.setAttribute('aria-expanded','false');field.removeAttribute('aria-activedescendant');index=-1;}\nfunction choose(row){chosen=row[2];selected.value=chosen;field.value=row[1]+' · '+row[2];field.setCustomValidity('');hint.textContent='Used automatically by every table in this club.';close();field.focus();}\nfunction results(){\n const query=field.value.trim().toLowerCase();\n let rows=data.rows.filter(row=>(row.join(' ')+' '+(aliases[row[0]]||'')).toLowerCase().includes(query));\n if(!rows.length&&query&&query.length<=24&&!/[<>]/.test(query))rows=[['CUSTOM','Custom currency / token',query.toUpperCase(),query]];\n list.replaceChildren();index=-1;\n rows.forEach((row,n)=>{\n  const button=document.createElement('button');button.type='button';button.tabIndex=-1;button.setAttribute('role','option');button.id=data.id+'-'+n;\n  if(data.flags[row[0].toLowerCase()]){const img=document.createElement('img');img.src='data:image/webp;base64,'+data.flags[row[0].toLowerCase()];img.alt='';img.width=20;img.height=15;button.append(img);}\n  else {const symbol=document.createElement('span');symbol.className='tr-currency-token';symbol.textContent=row[0]==='CR'?'◈':'¤';button.append(symbol);}\n  const text=document.createElement('span');text.textContent=row[1]+' · '+row[2];button.append(text);\n  button.addEventListener('pointerdown',event=>event.preventDefault());button.addEventListener('click',()=>choose(row));list.append(button);\n });\n if(chosen){index=rows.findIndex(row=>row[2]===chosen);if(index>=0){const options=list.querySelectorAll('[role=option]');options[index].setAttribute('aria-selected','true');field.setAttribute('aria-activedescendant',options[index].id);}}\n if(!rows.length){const message=document.createElement('span');message.className='tr-currency-empty';message.textContent='No matches. Search a country, currency or code.';list.append(message);}\n list.hidden=false;field.setAttribute('aria-expanded','true');\n}\nfield.addEventListener('focus',()=>{if(chosen)field.value='';results();});\nfield.addEventListener('input',()=>{chosen='';selected.value='';field.setCustomValidity('Choose a club currency from the results.');results();});\nfield.addEventListener('blur',()=>{if(chosen){const row=data.rows.find(row=>row[2]===chosen&&row[0]===({EUR:'EU'}[chosen]||chosen.slice(0,2)))||data.rows.find(row=>row[2]===chosen);field.value=row?row[1]+' · '+chosen:chosen;field.setCustomValidity('');}close();});\nfield.addEventListener('keydown',event=>{\n if(event.key==='Escape'){close();event.preventDefault();return;}\n if(event.key==='ArrowDown'||event.key==='ArrowUp'){\n  if(list.hidden)results();const options=Array.from(list.querySelectorAll('[role=option]'));if(!options.length)return;\n  event.preventDefault();index=(index+(event.key==='ArrowDown'?1:-1)+options.length)%options.length;\n  options.forEach((option,n)=>option.setAttribute('aria-selected',n===index?'true':'false'));\n  field.setAttribute('aria-activedescendant',options[index].id);options[index].scrollIntoView({block:'nearest'});\n }else if(event.key==='Enter'&&!list.hidden){const options=list.querySelectorAll('[role=option]');if(options.length){event.preventDefault();options[index<0?0:index].click();}}\n});\nif(chosen){const row=data.rows.find(row=>row[2]===chosen&&row[0]===({EUR:'EU'}[chosen]||chosen.slice(0,2)))||data.rows.find(row=>row[2]===chosen);field.value=row?row[1]+' · '+chosen:chosen;}\n})();\n"
